const norm = (s) => String(s).replace(/\r\n/g, '\n');
let applied = 0, skipped = 0, failed = 0;
const failures = [];
function run(cmd, args, label) {
  console.log('  $ ' + cmd + ' ' + args.join(' '));
  const r = spawnSync(cmd, args, { stdio: 'inherit', shell: process.platform === 'win32' });
  if (r.error || r.status !== 0) {
    console.log('[FAIL] ' + label + ' (exit ' + (r.status ?? r.error) + ')');
    return false;
  }
  console.log('[OK] ' + label);
  return true;
}
function selfClean() {
  // v2.4.23: cleanup is automatic — the user no longer has to delete
  // .bak files and old scripts by hand. Scoped patterns only: never a
  // bare *.cjs wildcard, never verify.cjs, never this script itself.
  console.log('');
  console.log('--- cleaning up (.bak files + older fix scripts) ---');
  const selfName = path.basename(__filename);
  let removed = 0;
  const tryDelete = (full, label) => {
    try {
      fs.unlinkSync(full);
      removed++;
      if (label) console.log('  removed: ' + label);
    } catch (e) {
      console.log('  (could not delete ' + label + ': ' + e.message + ')');
    }
  };
  for (const name of fs.readdirSync(process.cwd())) {
    if (name.endsWith('.bak')) tryDelete(path.join(process.cwd(), name), name);
  }
  const walkBak = (dir) => {
    for (const ent of fs.readdirSync(dir, { withFileTypes: true })) {
      const p = path.join(dir, ent.name);
      if (ent.isDirectory()) walkBak(p);
      else if (ent.name.endsWith('.bak')) tryDelete(p, path.relative(process.cwd(), p));
    }
  };
  const srcDir = path.join(process.cwd(), 'src');
  if (fs.existsSync(srcDir)) walkBak(srcDir);
  for (const name of fs.readdirSync(process.cwd())) {
    if (name === selfName) continue;
    if (name === 'verify.cjs') continue;
    if (name === 'fix-health-app.cjs' || /^fix-health-app-v2\.4\..*\.cjs$/.test(name)) {
      tryDelete(path.join(process.cwd(), name), name);
    }
  }
  console.log('[OK] cleanup: removed ' + removed + ' file(s)');
}
function main() {
  console.log('Family Health Track fix — v' + VERSION);
  console.log('Project folder: ' + process.cwd());
  const pkgPath = path.join(process.cwd(), 'package.json');
  if (!fs.existsSync(pkgPath)) {
    console.log('[ERROR] package.json not found here. Run this script from the project root (the folder with package.json).');
    process.exit(1);
  }
  let pkg;
  try { pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8')); } catch (e) {
    console.log('[ERROR] package.json could not be read: ' + e.message);
    process.exit(1);
  }
  if (pkg.name !== 'family-health-track') {
    console.log('[ERROR] This does not look like the Family Health Track project (package name: ' + pkg.name + '). Stopping.');
    process.exit(1);
  }
  if (String(pkg.version) === '2.4.21') {
    console.log('[ERROR] This project is still v2.4.21. Run fix-health-app-v2.4.22.cjs first, then run this script again.');
    process.exit(1);
  }
  if (![PREV_VERSION, VERSION].includes(String(pkg.version))) {
    console.log('[ERROR] Unexpected project version ' + pkg.version + ' (expected ' + PREV_VERSION + '). Stopping — ask for help before running this.');
    process.exit(1);
  }
  for (const f of FILES) {
    const dest = path.join(process.cwd(), ...f.path.split('/'));
    const next = Buffer.from(f.b64, 'base64').toString('utf8');
    try {
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      if (fs.existsSync(dest) && norm(fs.readFileSync(dest, 'utf8')) === norm(next)) {
        console.log('[SKIP] already applied: ' + f.path);
        skipped++;
        continue;
      }
      if (fs.existsSync(dest) && !fs.existsSync(dest + '.bak')) {
        fs.copyFileSync(dest, dest + '.bak');
      }
      fs.writeFileSync(dest, next, 'utf8');
      console.log('[OK] applied: ' + f.path);
      applied++;
    } catch (e) {
      console.log('[FAIL] ' + f.path + ': ' + e.message);
      failed++;
      failures.push(f.path + ': ' + e.message);
    }
  }
  for (const rel of DELETED) {
    const dest = path.join(process.cwd(), ...rel.split('/'));
    try {
      if (!fs.existsSync(dest)) {
        console.log('[SKIP] already deleted: ' + rel);
        skipped++;
        continue;
      }
      if (!fs.existsSync(dest + '.bak')) {
        fs.copyFileSync(dest, dest + '.bak');
      }
      fs.unlinkSync(dest);
      console.log('[OK] deleted: ' + rel + ' (backup saved as ' + rel + '.bak)');
      applied++;
    } catch (e) {
      console.log('[FAIL] ' + rel + ': ' + e.message);
      failed++;
      failures.push(rel + ': ' + e.message);
    }
  }
  console.log('');
  console.log('Applied ' + applied + ' | Already applied ' + skipped + ' | Failed ' + failed);
  if (failed > 0) {
    console.log('Failures: ' + failures.join(' ; '));
    console.log('Stopping before checks. Your .bak backups are next to the originals.');
    process.exit(1);
  }
  console.log('');
  console.log('--- checks (npm install, typecheck, tests, build) ---');
  const okInstall = run('npm', ['install', '--no-audit', '--no-fund'], 'npm install');
  const okLint = run('npx', ['tsc', '--noEmit'], 'typecheck (tsc --noEmit)');
  const okTest = run('npx', ['vitest', 'run'], 'tests (vitest run)');
  const okBuild = run('npm', ['run', 'build'], 'build (vite build)');
  if (!okInstall || !okLint || !okTest || !okBuild) {
    console.log('');
    console.log('[DONE WITH ERRORS] Files were updated, but a check failed above.');
    console.log('Do NOT deploy yet. Ask for help and include the error lines above.');
    process.exit(1);
  }
  // Checks passed — clean up .bak files and older fix scripts now.
  selfClean();
  console.log('');
  console.log('[DONE] v' + PREV_VERSION + ' → v' + VERSION + '. Applied ' + applied + ' | Already applied ' + skipped + ' | Failed 0');
  console.log('');
  console.log('NEXT STEPS (အဆင့်လိုက် လုပ်ပါ):');
  console.log('  1. ဒီဗားရှင်းမှာ firestore.rules အပြောင်းအလဲ မရှိဘူး —');
  console.log('     Console မှာ Publish လုပ်စရာ မလိုပါ။');
  console.log('  2. .bak file တွေနဲ့ အဟောင်း fix script တွေကို ဒီ script က');
  console.log('     အလိုအလျောက် ဖျက်ပြီးပါပြီ — ကိုယ်တိုင် ဖျက်စရာ မလိုပါ။');
  console.log('  3. App ကို push / deploy လုပ်ပါ:');
  console.log('       git add -A');
  console.log('       git commit -m "v2.4.23"');
  console.log('       git push');
  console.log('  4. deploy ပြီးရင် ၅ မိနစ်လောက် စောင့်ပြီး ဖုန်းမှာ');
  console.log('     hard-refresh တစ်ခါ လုပ်ပါ။');
  console.log('     Version History မှာ v2.4.23 ပြရပါမယ်။');
  console.log('  5. ဖုန်းမှာ ဒါတွေ စစ်ပါ (တစ်ခါတည်း အကုန်):');
  console.log('     (1) Trends မျက်နှာပြင် — အစိမ်းရောင် ခေါင်းစဉ်ကတ်');
  console.log('         သေးသွားပြီး ကျန်းမာရေးအဆင့် စာကြောင်း တစ်ကြောင်း');
  console.log('         တည်း ဖြစ်ရမယ်; Database ကတ်တွေ ဖုန်းမှာ ၂ ခုစီ');
  console.log('         ဘေးချင်းယှဉ် ပြရမယ်။');
  console.log('     (2) ဖုန်းမှာ ဘေးတိုက် ပွတ်ဆွဲစရာ လုံးဝ မရှိတော့ဘူး —');
  console.log('         BMI ဂရပ်က အကြံပြုချက်လေး ဘေးမရောက်တော့ဘူး။');
  console.log('     (3) Reminders မှာ "အားလုံး ဖျက်မည်"၊ Lab မှာ');
  console.log('         "အားလုံးရှင်းမည်" လို့ ပြရမယ်။');
  console.log('     (4) Version Update modal — v2.4.23 နဲ့တကွ');
  console.log('         ပြင်ထားတာ အကျဉ်းချုပ် (၄ ချက်) ပြရမယ်၊');
  console.log('         တစ်ကြိမ်ပဲ ပြရမယ် (ပြန်ဖွင့်တိုင်း ထပ်မပြဘူး)။');
  console.log('     (5) မှတ်တမ်း အသစ်တစ်ခု ထည့်ကြည့်ပါ — သိမ်းတာ');
  console.log('         အဆင်ပြေရမယ်; လမ်းညွှန် (guide) မျက်နှာပြင်မှာ');
  console.log('         အမှန်ခြစ်ထားတာ ပြန်ဖွင့်လည်း ကျန်နေရမယ်။');
}
main();
